#!/usr/bin/env python3
# SPDX-License-Identifier: BSD-2-Clause
"""Generate the fuzzing corpus seeds for the SYS fuzz targets on the fly.

The sys-prepare and sys-execute fuzz targets need small seed inputs to
fuzz effectively. Instead of checking binary seed files into the
repository, this script writes them into a directory of choice, e.g.:

    ./test/fuzz/gen_corpus.py --output test/fuzz/seeds
"""
import argparse
import base64
import os

# Seeds are stored as base64 so the repository stays free of binary blobs.
# Paths are relative to the corpus root directory.
SEEDS = {
    # Tss2_Sys_*_Prepare command skeletons (sys-prepare fuzz targets)
    "prepare/Tss2_Sys_CreatePrimary_Prepare/skel0.bin":
        "",
    "prepare/Tss2_Sys_CreatePrimary_Prepare/skel1.bin":
        "",
    "prepare/Tss2_Sys_Create_Prepare/skel0.bin":
        "",
    "prepare/Tss2_Sys_Create_Prepare/skel1.bin":
        "",
    "prepare/Tss2_Sys_Create_Prepare/skel2.bin":
        "",
    "prepare/Tss2_Sys_NV_DefineSpace_Prepare/skel0.bin":
        "AAAAAAAAAAIQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    "prepare/Tss2_Sys_NV_DefineSpace_Prepare/skel1.bin":
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    "prepare/Tss2_Sys_StartAuthSession_Prepare/skel0.bin":
        "AwAAAAwAAEAjAAsAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    "prepare/Tss2_Sys_StartAuthSession_Prepare/skel1.bin":
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    # Tss2_Sys_Execute response buffers (sys-execute fuzz target)
    "sys-execute/certify-attest-rsassa.bin":
        "",
    "sys-execute/contextsave-tpms-context.bin":
        "gAIAAAA2AAAAAAAAACgAAAAAAAAACYAAAAFAAAABABgAIAALABBaWlpaWlpaWlpaWlpaWlpa",
    "sys-execute/getcapability-algs.bin":
        "gAEAAAAaAAAAAAAAAAALAAAAAQABAQAAAAU=",
    "sys-execute/getcapability-props.bin":
        "gAEAAAAbAAAAAAAAAAAMAAAAAQAAAQAAAAAD",
    "sys-execute/getrandom-digest.bin":
        "gAEAAAAsAAAAAAAgqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqo=",
    "sys-execute/min-success-nosess.bin":
        "gAEAAAAKAAAAAA==",
    "sys-execute/min-success-sess.bin":
        "gAIAAAAOAAAAAAAAAAA=",
    "sys-execute/oversize-response.bin":
        "gAIA////AAAAAA==",
    "sys-execute/quote-attest-ecdsa.bin":
        "gAIAAACrAAAAAAAAAJ0AU/9UQ0eAGAAEu7u7uwAAAAAAAAAAA+gAAAAyAAAAAAAAAAfMzMzMzMzMAATd3d3dAAurq6urq6urq6urq6urq6urq6urq6urq6urq6urq6urqwAYAAsAIwAgEREREREREREREREREREREREREREREREREREREREREREAICIiIiIiIiIiIiIiIiIiIiIiIiIiIiIiIiIiIiIiIiIi",
    "sys-execute/rc-failure.bin":
        "gAEAAAAKAAABAQ==",
    "sys-execute/rc-initialize.bin":
        "gAEAAAAKAAABAA==",
    "sys-execute/readclock-timeinfo.bin":
        "gAIAAAArAAAAAAAAAB0AAAAAAAAAAQAAAAAAAAACAAAAAwAAAAQAAAAFAQ==",
    "sys-execute/sessions-tpm2b-public-rsa.bin":
        "",
    "sys-execute/truncated-header.bin":
        "gAEAAA==",
}

def main():
    parser = argparse.ArgumentParser(
        description="Generate fuzzing corpus seeds for the SYS fuzz targets.")
    parser.add_argument("-o", "--output", default="test/fuzz/seeds",
                        help="directory to write the seed corpus into "
                             "(default: %(default)s)")
    args = parser.parse_args()

    for path, data in SEEDS.items():
        target = os.path.join(args.output, path)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as seed_file:
            seed_file.write(base64.b64decode(data))
        print("wrote %s" % target)


if __name__ == "__main__":
    main()
